import { percentOf } from "./money.ts";

/** Tax rate in percent, by country. */
export const TAX_PERCENT = {
  US: 0,
  DE: 19,
  GB: 20,
} as const;

export type Country = keyof typeof TAX_PERCENT;

/** Tax in cents on a net amount in cents. */
export function taxOn(netCents: number, country: Country): number {
  return percentOf(netCents, TAX_PERCENT[country]);
}
