  const changes = JSON.parse(readFileSync(new URL("../changes.json", import.meta.url), "utf8"));
  const version = process.argv[2] ?? "unreleased";
  console.log(renderRelease(version === "unreleased" ? "Unreleased" : version, changes[version] ?? []));
}
